package vip.xiaonuo.srm.collaboration;
import java.util.*;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import org.springframework.context.event.EventListener;
import vip.xiaonuo.flow.api.*;
import vip.xiaonuo.srm.api.SrmSupplierAccessApi.Context;
import static vip.xiaonuo.srm.collaboration.CollaborationStore.*;
import static vip.xiaonuo.srm.collaboration.CollaborationRules.*;
import static vip.xiaonuo.srm.collaboration.CollaborationInputs.*;
@Service @RequiredArgsConstructor @Transactional(isolation=Isolation.READ_COMMITTED)
public class CollaborationCases {
 final CollaborationStore x;final SettlementService settlements;final OrdersService orders;final SrmFlowApi flow;
 Map<String,Object> row(Context a,String id,boolean lock){var rows=x.db.queryForList("SELECT * FROM SRM_COL_CASE WHERE ID=?"+(lock?" FOR UPDATE":""),id);require(rows.size()==1,404,"处理申请不存在");var c=rows.get(0);x.access.requireSupplier(a,s(c,"SUPPLIER_ID"),false);if(s(c,"KIND").equals("RECON_DISPUTE"))x.recon(a,s(c,"BUSINESS_ID"),false);else{var receipt=x.aggregate(a,"SRM_COL_RECEIPT",s(c,"BUSINESS_ID"),false);x.po(a,s(receipt,"PO_ID"),false);}return c;}
 Map<String,Object> basis(Map<String,Object> parent,String kind){if(kind.equals("RECON_DISPUTE")){settlements.validate(parent);return Map.of("recNo",parent.get("REC_NO"),"amount",x.clearAmount(parent,"AMOUNT_CIPHER"),"currency",parent.get("CURRENCY"),"basisHash",parent.get("BASIS_HASH"));}require(s(parent,"STATUS").equals("POSTED")&&parent.get("CONNECTOR_ID")==null,409,"仅人工实收可申请冲销，ERP实收应由来源系统纠正");require(x.db.queryForObject("SELECT COUNT(*) FROM SRM_COL_RECEIPT_LINE WHERE RECEIPT_ID=? AND ALLOC_RECON_ID IS NOT NULL",Long.class,parent.get("ID"))==0,409,"实收已占用对账，不可冲销");return Map.of("receiptNo",parent.get("RECEIPT_NO"),"rowVersion",parent.get("ROW_VERSION"),"lines",x.db.queryForList("SELECT ID,QUANTITY,UNIT_PRICE_CIPHER,AMOUNT_CIPHER FROM SRM_COL_RECEIPT_LINE WHERE RECEIPT_ID=? ORDER BY ID",parent.get("ID")));}
 Map<String,Object> parent(Context a,String kind,String id){if(kind.equals("RECON_DISPUTE"))return x.lockRecon(a,id);var r=x.aggregate(a,"SRM_COL_RECEIPT",id,false);x.lockPo(a,s(r,"PO_ID"));return x.aggregate(a,"SRM_COL_RECEIPT",id,true);}
 public Map<String,Object> submit(Context a,String kind,String business,Opinion p){if(kind.equals("RECON_DISPUTE"))settlements.participant(a);else x.buyer(a);var r=parent(a,kind,business);x.version(r,p.rowVersion());if(kind.equals("RECON_DISPUTE")){settlements.financeLock(r);require(Set.of("DIFFERENCE","DISPUTED").contains(s(r,"STATUS")),409,"请先记录对账差异");}require(x.db.queryForObject("SELECT COUNT(*) FROM SRM_COL_CASE WHERE BUSINESS_ID=? AND KIND=? AND STATUS='PENDING'",Long.class,business,kind)==0,409,"已有待经理处理申请");var snapshot=basis(r,kind);String id=id();String pid=flow.start("srm_col_review",id,Map.of("approvalId",id,"requestedBy",a.userId(),"businessType","COL_REVIEW"));x.db.update("INSERT INTO SRM_COL_CASE(ID,ORG_ID,SUPPLIER_ID,KIND,BUSINESS_ID,PROCESS_ID,STATUS,SNAPSHOT_CIPHER,BASIS_HASH,REASON_CIPHER,REQUESTED_BY,CREATED_AT) VALUES(?,?,?,?,?,?,'PENDING',?,?,?,?,NOW(3))",id,r.get("ORG_ID"),r.get("SUPPLIER_ID"),kind,business,pid,x.crypto.encrypt(x.json(snapshot)),x.hash(snapshot),x.crypto.encrypt(p.comment()),a.userId());if(kind.equals("RECON_DISPUTE"))x.db.update("UPDATE SRM_COL_RECON SET STATUS='DISPUTED',BUYER_CONFIRMED=false,SUPPLIER_CONFIRMED=false,ROW_VERSION=ROW_VERSION+1 WHERE ID=?",business);x.audit(a,s(r,"SUPPLIER_ID"),id,"COLLABORATION_REVIEW_REQUESTED",Map.of("kind",kind,"basisHash",x.hash(snapshot)));return detail(a,id);}
 public Map<String,Object> detail(Context a,String id){var c=row(a,id,false);var out=x.basic(c,new String[][]{{"id","ID"},{"kind","KIND"},{"businessId","BUSINESS_ID"},{"status","STATUS"},{"requestedBy","REQUESTED_BY"},{"reviewedBy","REVIEWED_BY"},{"createdAt","CREATED_AT"}});out.put("reason",x.crypto.decrypt(s(c,"REASON_CIPHER")));var visible=x.object(x.crypto.decrypt(s(c,"SNAPSHOT_CIPHER")));if(visible.get("lines") instanceof List<?> ls)for(Object item:ls)if(item instanceof Map<?,?> m){m.remove("UNIT_PRICE_CIPHER");m.remove("AMOUNT_CIPHER");}out.put("basis",visible);out.put("tasks",a.portal()?List.of():flow.tasks(s(c,"PROCESS_ID")));out.put("reviewComment",s(c,"REVIEW_COMMENT_CIPHER").isBlank()?"":x.crypto.decrypt(s(c,"REVIEW_COMMENT_CIPHER")));return out;}
 boolean reviewer(Context a,Map<String,Object> c,Map<String,Object> t){return !a.portal()&&x.has(a,"CAT-MGR","superAdmin")&&!a.userId().equals(c.get("REQUESTED_BY"))&&(s(t,"assignee").isBlank()||a.userId().equals(t.get("assignee")));}
 public List<Map<String,Object>> tasks(Context a){x.buyer(a);var out=new ArrayList<Map<String,Object>>();for(var c:x.db.queryForList("SELECT * FROM SRM_COL_CASE WHERE STATUS='PENDING' ORDER BY CREATED_AT LIMIT 1000")){try{row(a,s(c,"ID"),false);}catch(vip.xiaonuo.common.exception.CommonException e){if(e.getCode()==404||e.getCode()==403)continue;throw e;}for(var t:flow.tasks(s(c,"PROCESS_ID")))if(reviewer(a,c,t)){var item=new LinkedHashMap<String,Object>(t);item.put("caseId",c.get("ID"));item.put("kind",c.get("KIND"));out.add(item);}}return out;}
 public Map<String,Object> decide(Context a,String id,String tid,CaseDecision p){var first=row(a,id,false);var r=parent(a,s(first,"KIND"),s(first,"BUSINESS_ID"));var c=row(a,id,true);require(s(c,"STATUS").equals("PENDING"),409,"申请已处理");var t=flow.task(tid);require(flow.tasks(s(c,"PROCESS_ID")).stream().anyMatch(task->tid.equals(task.get("id"))),404,"任务不属于本申请");require(reviewer(a,c,t),403,"无经理权限或不能审批本人申请");if(p.action().equals("REJECT")){flow.stop(s(c,"PROCESS_ID"),"REJECTED");x.db.update("UPDATE SRM_COL_CASE SET STATUS='REJECTED',REVIEWED_BY=?,REVIEW_COMMENT_CIPHER=?,CLOSED_AT=NOW(3) WHERE ID=?",a.userId(),x.crypto.encrypt(p.comment()),id);}else{require(x.hash(basis(r,s(c,"KIND"))).equals(c.get("BASIS_HASH")),409,"处理依据已变化，请撤回后重新提交");x.db.update("UPDATE SRM_COL_CASE SET REVIEWED_BY=?,REVIEW_COMMENT_CIPHER=? WHERE ID=?",a.userId(),x.crypto.encrypt(p.comment()),id);flow.complete(tid,Map.of("decisionActor",a.userId()));require(flow.ended(s(c,"PROCESS_ID")),409,"仍有未完成审批任务");}x.db.update("INSERT INTO SRM_COL_CASE_ACTION VALUES(?,?,?,?,?,NOW(3))",id(),id,p.action(),a.userId(),x.crypto.encrypt(p.comment()));x.audit(a,s(c,"SUPPLIER_ID"),id,"COL_REVIEW_"+p.action(),Map.of("taskId",tid));return detail(a,id);}
 @EventListener public void completed(SrmFlowCompleted e){var rows=x.db.queryForList("SELECT * FROM SRM_COL_CASE WHERE ID=?",e.approvalId());if(rows.isEmpty())return;var c=rows.get(0);Context a=new Context(e.actorId(),s(c,"ORG_ID"),null,Set.of("BUYER","CAT-MGR","SYSTEM"),false,Set.of(s(c,"ORG_ID")),false,false);var r=parent(a,s(c,"KIND"),s(c,"BUSINESS_ID"));c=row(a,e.approvalId(),true);require(s(c,"STATUS").equals("PENDING")&&s(c,"PROCESS_ID").equals(e.processId())&&e.actorId().equals(c.get("REVIEWED_BY"))&&!e.actorId().equals(c.get("REQUESTED_BY")),409,"经理审批回写关联不一致");require(x.hash(basis(r,s(c,"KIND"))).equals(c.get("BASIS_HASH")),409,"审批依据变化");if(s(c,"KIND").equals("RECON_DISPUTE")){settlements.financeLock(r);x.db.update("UPDATE SRM_COL_RECON SET STATUS='WAITING_CONFIRMATION',BUYER_CONFIRMED=false,SUPPLIER_CONFIRMED=false,ROW_VERSION=ROW_VERSION+1 WHERE ID=?",r.get("ID"));}else{x.db.update("UPDATE SRM_COL_RECEIPT SET STATUS='REVERSED',ROW_VERSION=ROW_VERSION+1 WHERE ID=?",r.get("ID"));var asn=x.db.queryForMap("SELECT * FROM SRM_COL_ASN WHERE ID=? FOR UPDATE",r.get("ASN_ID"));var po=x.po(a,s(r,"PO_ID"),false);orders.refreshAsn(po,asn,false);x.refreshPo(s(po,"ID"));}x.db.update("UPDATE SRM_COL_CASE SET STATUS='APPROVED',CLOSED_AT=NOW(3) WHERE ID=?",c.get("ID"));x.notifyBoth(r,s(c,"BUSINESS_ID"),"COL_REVIEW_APPROVED","经理处理完成，请重新核对业务单据",s(c,"ID")+":approved");}
 public void withdraw(Context a,String id){var first=row(a,id,false);parent(a,s(first,"KIND"),s(first,"BUSINESS_ID"));var c=row(a,id,true);require(a.userId().equals(c.get("REQUESTED_BY"))||x.has(a,"superAdmin"),403,"仅申请人可撤回");require(s(c,"STATUS").equals("PENDING"),409,"申请已处理");flow.stop(s(c,"PROCESS_ID"),"WITHDRAWN");x.db.update("UPDATE SRM_COL_CASE SET STATUS='WITHDRAWN',CLOSED_AT=NOW(3) WHERE ID=?",id);}
}
